"""Generate the loop keyframes at the bottom of panel-rows.css.

panel.html's demos are CSS loops: every moving piece carries a class that
names its keyframes and the moment it acts in the loop (a-show-28 rises in
at 28%, a-tap-8 is a cursor press at 8%, ...). This script writes those
keyframes and classes. Everything in panel-rows.css above the line

    /* ---------- the loops (generated by tools/gen-panel-rows-css.py ...

is hand-written and kept as is; everything below it is replaced.

Add a timing a row needs to the lists below, run

    python tools/gen-panel-rows-css.py

and bump the shared ?v= token (CLAUDE.md). Resting styles are the finished
screen, so every animation's last frames return to its start (the loop
starts over) while the class's base style, when it has one, is the end.
"""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
CSS = os.path.join(HERE, '..', 'panel-rows.css')
MARKER = '/* ---------- the loops (generated by tools/gen-panel-rows-css.py'

END, RESET = 92, 97  # the screen holds until END%, then everything returns by RESET%

keys, rules = [], []


def pc(x):
    return f'{round(x, 2):g}%'


def kf(name, frames):
    return f'@keyframes {name} {{ ' + ' '.join(f'{k} {{ {v} }}' for k, v in frames) + ' }'


def add(kind, at, frames, timing='', base=''):
    tag = f'{kind}-{at}'
    keys.append(kf(f'pr-{tag}', frames))
    rules.append(f'.prows-anim .a-{tag} {{ animation: pr-{tag} var(--loop) infinite{timing}; }}')
    if base:
        rules.append(f'.a-{tag} {{ {base} }}')


EASE = ' cubic-bezier(.2, .7, .2, 1)'

# rise in at a%
for a in [10, 14, 20, 24, 26, 28, 34, 38, 40, 44, 50, 52, 60, 66]:
    add('show', a, [(f'0%, {pc(a)}', 'opacity: 0; transform: translateY(8px);'),
                    (f'{pc(a + 4)}, {END}%', 'opacity: 1; transform: none;'),
                    (f'{RESET}%, 100%', 'opacity: 0; transform: none;')], EASE)
# a starting value that gives way at a% (gone when settled)
for a in [12, 16, 22, 50]:
    add('hide', a, [(f'0%, {pc(a)}', 'opacity: 1;'), (f'{pc(a + 3)}, {END}%', 'opacity: 0;'),
                    (f'{RESET}%, 100%', 'opacity: 1;')], base='opacity: 0;')
# a final value that takes over at a%
for a in [10, 12, 22, 28, 40, 50, 66]:
    add('fade', a, [(f'0%, {pc(a)}', 'opacity: 0;'), (f'{pc(a + 3)}, {END}%', 'opacity: 1;'),
                    (f'{RESET}%, 100%', 'opacity: 0;')])
# shown only between a% and b% (gone when settled), and its opposite
for a, b in [(22, 40), (10, 24), (24, 38), (38, 52), (52, 66)]:
    add('blink', f'{a}-{b}', [(f'0%, {a}%', 'opacity: 0;'), (f'{pc(a + 1.5)}, {b}%', 'opacity: 1;'),
                              (f'{pc(b + 1.5)}, 100%', 'opacity: 0;')], base='opacity: 0;')
add('gap', '22-40', [('0%, 22%', 'opacity: 1;'), ('23.5%, 40%', 'opacity: 0;'), ('41.5%, 100%', 'opacity: 1;')])
# handled: dims at a%
add('dim', 66, [('0%, 66%', 'opacity: 1;'), (f'69%, {END}%', 'opacity: .5;'), (f'{RESET}%, 100%', 'opacity: 1;')],
    base='opacity: .5;')

# the cursor: glides in, presses at a%, leaves; its ring spreads on the press
for a in [6, 8, 10, 19, 34, 46, 54, 62]:
    keys.append(kf(f'pr-tap-{a}', [
        (f'0%, {pc(a - 5)}', 'opacity: 0; transform: translate(26px, 30px);'),
        (pc(a - 1), 'opacity: 1; transform: none;'),
        (pc(a), 'transform: scale(.8);'),
        (pc(a + 1.5), 'opacity: 1; transform: none;'),
        (f'{pc(a + 6)}, 100%', 'opacity: 0; transform: translate(-6px, 10px);'),
    ]))
    keys.append(kf(f'pr-ring-{a}', [
        (f'0%, {pc(a)}', 'opacity: 0; transform: scale(.2);'),
        (pc(a + .5), 'opacity: .8; transform: scale(.4);'),
        (f'{pc(a + 6)}, 100%', 'opacity: 0; transform: scale(2.4);'),
    ]))
    rules.append(f'.prows-anim .a-tap-{a} {{ animation: pr-tap-{a} var(--loop) cubic-bezier(.3, .7, .3, 1) infinite; }}')
    rules.append(f'.prows-anim .a-tap-{a}::after {{ animation: pr-ring-{a} var(--loop) ease-out infinite; }}')

# the calendar's drag: the cursor grabs the appointment at 10%, carries it
# to its new place by 24%, lets go
keys.append(kf('pr-grab-10-26', [
    ('0%, 5%', 'opacity: 0; transform: translate(26px, 30px);'),
    ('9%', 'opacity: 1; transform: none;'),
    ('10%', 'transform: scale(.8);'),
    ('12%, 25%', 'opacity: 1; transform: none;'),
    ('31%, 100%', 'opacity: 0; transform: translate(-6px, 10px);'),
]))
rules.append('.prows-anim .a-grab-10-26 { animation: pr-grab-10-26 var(--loop) cubic-bezier(.3, .7, .3, 1) infinite; }')
rules.append('.prows-anim .a-grab-10-26::after { animation: pr-ring-10 var(--loop) ease-out infinite; }')
add('drag', '10-26', [
    ('0%, 10%', 'transform: translate(var(--dx), var(--dy)); outline: 2px solid transparent;'),
    ('12%', 'transform: translate(var(--dx), var(--dy)) scale(1.05); outline: 2px solid var(--teal);'),
    ('24%', 'transform: scale(1.05); outline: 2px solid var(--teal);'),
    (f'27%, {END}%', 'transform: none; outline: 2px solid transparent;'),
    (f'{RESET}%, 100%', 'transform: translate(var(--dx), var(--dy)); outline: 2px solid transparent;'),
], ' cubic-bezier(.4, 0, .2, 1)')

# tabs and segments: off -> on at a%, and the one giving way
TON = 'background: var(--teal-deep); border-color: var(--teal-deep); color: #fff;'
TOFF = 'background: var(--surface); border-color: var(--line); color: var(--ink-soft);'
for a in [14, 38, 50]:
    add('on', a, [(f'0%, {pc(a)}', TOFF), (f'{pc(a + 2)}, {END}%', TON), (f'{RESET}%, 100%', TOFF)])
    add('off', a, [(f'0%, {pc(a)}', TON), (f'{pc(a + 2)}, {END}%', TOFF), (f'{RESET}%, 100%', TON)])
# colour swatches and the launcher dot that takes the picked colour
SON = 'border-color: var(--surface); box-shadow: 0 0 0 2px var(--teal-deep);'
SOFF = 'border-color: transparent; box-shadow: 0 0 0 1px rgba(0, 0, 0, .08);'
add('swon', 12, [('0%, 12%', SOFF), (f'14%, {END}%', SON), (f'{RESET}%, 100%', SOFF)])
add('swoff', 12, [('0%, 12%', SON), (f'14%, {END}%', SOFF), (f'{RESET}%, 100%', SON)])
add('dot', 12, [('0%, 12%', 'background: var(--teal);'), (f'14%, {END}%', 'background: #c2612f;'),
                (f'{RESET}%, 100%', 'background: var(--teal);')])
# a choice card picked
add('pick', 10, [('0%, 10%', 'border-color: var(--line); box-shadow: none;'),
                 (f'12%, {END}%', 'border-color: var(--teal-deep); box-shadow: 0 0 0 1px var(--teal-deep);'),
                 (f'{RESET}%, 100%', 'border-color: var(--line); box-shadow: none;')])
# the check mark drawing itself
for a in [48, 70]:
    add('draw', a, [(f'0%, {a}%', 'stroke-dashoffset: 24;'), (f'{a + 5}%, {END}%', 'stroke-dashoffset: 0;'),
                    (f'{RESET}%, 100%', 'stroke-dashoffset: 24;')])
    rules.append(f'.a-draw-{a} {{ stroke-dasharray: 24; }}')
# the embed line's copied glow
add('glow', 38, [('0%, 38%', 'box-shadow: 0 0 0 0 rgba(15, 138, 134, .6);'),
                 ('48%, 100%', 'box-shadow: 0 0 0 11px rgba(15, 138, 134, 0);')])
# the launcher moving corners
add('slide', 40, [('0%, 40%', 'transform: translateX(var(--from));'), (f'46%, {END}%', 'transform: none;'),
                  (f'{RESET}%, 100%', 'transform: translateX(var(--from));')], ' cubic-bezier(.2, .8, .2, 1)')
# the on switch
add('swtrack', 58, [('0%, 58%', 'background: #cfcabd;'), (f'61%, {END}%', 'background: var(--teal);'),
                    (f'{RESET}%, 100%', 'background: #cfcabd;')])
add('swknob', 58, [('0%, 58%', 'transform: none;'), (f'61%, {END}%', 'transform: translateX(13px);'),
                   (f'{RESET}%, 100%', 'transform: none;')])
# chart bars growing up, treatment bars growing across
for a in range(30, 53, 2):
    add('grow', a, [(f'0%, {a}%', 'transform: scaleY(0);'), (f'{a + 6}%, {END}%', 'transform: scaleY(1);'),
                    (f'{RESET}%, 100%', 'transform: scaleY(0);')], ' cubic-bezier(.2, .8, .2, 1)')
for a in [50, 54, 58]:
    add('growx', a, [(f'0%, {a}%', 'transform: scaleX(0);'), (f'{a + 8}%, {END}%', 'transform: scaleX(1);'),
                     (f'{RESET}%, 100%', 'transform: scaleX(0);')], ' cubic-bezier(.2, .8, .2, 1)')
# typing: Hebrew reveals from the right, the URL from the left; un-typing
# at the end fades instead of sliding back
for a, b in [(16, 38), (8, 30)]:
    keys.append(f'@keyframes pr-type-{a}-{b} {{ 0%, {a}% {{ clip-path: inset(0 0 0 100%); opacity: 1; animation-timing-function: steps(26, end); }} '
                f'{b}%, {END}% {{ clip-path: inset(0); opacity: 1; }} {RESET - 1}% {{ clip-path: inset(0); opacity: 0; }} '
                f'{RESET}%, 100% {{ clip-path: inset(0 0 0 100%); opacity: 0; }} }}')
    rules.append(f'.prows-anim .a-type-{a}-{b} {{ animation: pr-type-{a}-{b} var(--loop) infinite; }}')
keys.append(f'@keyframes pr-typel-4-16 {{ 0%, 4% {{ clip-path: inset(0 100% 0 0); opacity: 1; animation-timing-function: steps(24, end); }} '
            f'16%, {END}% {{ clip-path: inset(0); opacity: 1; }} {RESET - 1}% {{ clip-path: inset(0); opacity: 0; }} '
            f'{RESET}%, 100% {{ clip-path: inset(0 100% 0 0); opacity: 0; }} }}')
rules.append('.prows-anim .a-typel-4-16 { animation: pr-typel-4-16 var(--loop) infinite; }')

with open(CSS, encoding='utf-8') as f:
    css = f.read()
i = css.index(MARKER)
head = css[:css.index('\n', i) + 1]
with open(CSS, 'w', encoding='utf-8', newline='\n') as f:
    f.write(head + '\n'.join(keys) + '\n\n' + '\n'.join(rules) + '\n')
print(f'{len(keys)} keyframes, {len(rules)} rules')
